/**
 * ParaViewExporter - export computed near-field data as a VTU file for ParaView.
 *
 * The file is written in the browser from the fields already computed for the
 * view. It used to be generated by the backend from placeholder zero currents,
 * so every exported field was zero (and its inline "binary" arrays lacked the
 * byte-count header VTK expects). ASCII arrays need no header; each point is a
 * VTK_VERTEX cell so ParaView shows it without a Glyph filter.
 */

import type { RootState } from '@/store';
import { downloadFile } from './exportData';

interface ExportToVTUOptions {
  fieldId: string;
  frequencyHz: number;
  filename: string;
}

type ComplexVector = {
  x: { real: number; imag: number };
  y: { real: number; imag: number };
  z: { real: number; imag: number };
};

export interface VtuFieldData {
  points: Array<[number, number, number]> | number[][];
  E_mag?: number[];
  H_mag?: number[];
  E_vectors?: ComplexVector[];
  H_vectors?: ComplexVector[];
}

const VTK_VERTEX = 1;

const num = (v: number) => (Number.isFinite(v) ? String(Math.fround(v)) : '0');

function dataArray(name: string, values: number[], components = 1, type = 'Float32'): string {
  const comps = components > 1 ? ` NumberOfComponents="${components}"` : '';
  return `        <DataArray type="${type}" Name="${name}"${comps} format="ascii">\n          ${values
    .map(type === 'Float32' ? num : String)
    .join(' ')}\n        </DataArray>`;
}

function vectorParts(vectors: ComplexVector[], part: 'real' | 'imag'): number[] {
  return vectors.flatMap((v) => [v.x[part], v.y[part], v.z[part]]);
}

/** VTU (VTK UnstructuredGrid, XML, ASCII) with one vertex cell per point. */
export function buildVtu(data: VtuFieldData, frequencyHz: number): string {
  const n = data.points.length;
  const pointData: string[] = [];
  if (data.E_mag?.length === n) pointData.push(dataArray('E_Magnitude', data.E_mag));
  if (data.H_mag?.length === n) pointData.push(dataArray('H_Magnitude', data.H_mag));
  if (data.E_vectors?.length === n) {
    pointData.push(dataArray('E_Field_Real', vectorParts(data.E_vectors, 'real'), 3));
    pointData.push(dataArray('E_Field_Imag', vectorParts(data.E_vectors, 'imag'), 3));
  }
  if (data.H_vectors?.length === n) {
    pointData.push(dataArray('H_Field_Real', vectorParts(data.H_vectors, 'real'), 3));
    pointData.push(dataArray('H_Field_Imag', vectorParts(data.H_vectors, 'imag'), 3));
  }
  const indices = Array.from({ length: n }, (_, i) => i);
  return `<?xml version="1.0"?>
<VTKFile type="UnstructuredGrid" version="1.0" byte_order="LittleEndian">
  <UnstructuredGrid>
    <FieldData>
${dataArray('Frequency_MHz', [frequencyHz / 1e6])}
    </FieldData>
    <Piece NumberOfPoints="${n}" NumberOfCells="${n}">
      <PointData>
${pointData.join('\n')}
      </PointData>
      <Points>
${dataArray('Points', data.points.flat(), 3)}
      </Points>
      <Cells>
${dataArray('connectivity', indices, 1, 'Int32')}
${dataArray('offsets', indices.map((i) => i + 1), 1, 'Int32')}
${dataArray('types', indices.map(() => VTK_VERTEX), 1, 'UInt8')}
      </Cells>
    </Piece>
  </UnstructuredGrid>
</VTKFile>
`;
}

/**
 * Export field data to VTU format for ParaView visualization
 * @throws Error if field data is not found
 */
export async function exportToVTU(options: ExportToVTUOptions, state: RootState): Promise<void> {
  const { fieldId, frequencyHz, filename } = options;
  const fieldData = state.solver.fieldData?.[fieldId]?.[frequencyHz];

  if (!fieldData) {
    throw new Error(
      `No field data available for export (Field: ${fieldId}, Frequency: ${(frequencyHz / 1e6).toFixed(2)} MHz)`
    );
  }
  if (!fieldData.points || fieldData.points.length === 0) {
    throw new Error('Field data has no observation points');
  }

  downloadFile(buildVtu(fieldData, frequencyHz), `${filename}.vtu`, 'application/xml');
}

/**
 * Check if field data is available for export
 */
export function canExportToVTU(fieldId: string, frequencyHz: number, state: RootState): boolean {
  const fieldData = state.solver.fieldData?.[fieldId]?.[frequencyHz];
  return !!(
    fieldData &&
    fieldData.points &&
    fieldData.points.length > 0 &&
    (fieldData.E_mag || fieldData.H_mag || fieldData.E_vectors || fieldData.H_vectors)
  );
}
